  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "定义了设计条件、候选、条件格、证书输出、已知 token 与全层已提交 KV 的不同前沿，并固定时间量及统计人群。驻留公式明确唯一物理对象和同时存活关系，足以解释本章设计推导的输入、输出与状态。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "输出不是单一总分，而是对每个条件格 k 和候选 d 给出设计证书：合法性、状态转移、各资源成本、证据支持的上下界、质量状态、排除理由，以及下一步区分实验。"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "已生成文本不等于对应 KV 已计算；物理页已提交也不等于所有异步读者已经结束。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "区分函数、数值、设备、身份与并发条件和可替换设计选择。质量三态及作用域失配规则明确，分类函数显式消费质量状态；时间通过但质量失败或未知时均不能 VERIFIED。R1-LEGAL-01 已修复。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "任何一层失败都不能用平均更快抵消。允许近似的任务可以比较不同表示或求解轨迹，但必须把相应质量门槛写入 Q。"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "同作用域 `fail` 排除当前候选，`unknown` 保留候选但禁止 `VERIFIED`。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "SYNTHESIZE 给出归一化、逐格逐候选检查、容量未决保留、证据过滤与相交、质量门控、局部排除、全局删除和实验后重算。classify 与声明的单目标、容量已决范围一致。宽松上界超标保留开放，直接观测和统计失败证据另行处理，R1-ALG-01 已修复。组合轨迹区分采样与 KV 生产，处理缺 logits 的完整命中及取消后的物理完成；具体执行机制通过相关章节衔接。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "否则：记录该目标时间开放；宽松上界超目标仍留在这里"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "只有在全部目标格均已确认非法或获支持排除时，才从本轮全局候选集中删除"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "取消阻止未来业务提交，但不提前释放设备仍读取的页。读者结束后再降低相应执行引用；迟到通知只结算旧轮次，不写回新视图或下一生命期。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "六类成本均有具体对象和误算边界；资源需求除以服务能力的下界保留必要需求、能力上限和串行依赖前提。独立复算确认 KV 为 49152 B/token，容量主项为 5.75、11、10.75 GiB，CPU 各候选时间及布局复用阈值正确。共享容量去重与逐请求流量、共享与独立带宽域、吞吐与 ITL 均未混用。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "要作为有排除效力的下界，A_j 必须确为必需需求，B_j 必须是能力上限或明示模型设定，而不能用一次偏慢实测的带宽假装不可突破的硬上限。"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "同一合法转换结果可复用 R 次时，新路径总成本为 0.5＋0.6R ms，原路径为 R ms，严格获益要求 R>1.25；R＝2 时为 1.7 对 2.0 ms。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "解释了条件变化怎样保留身份和完成不变量、使证据过期、改变资源成本与候选资格。独立带宽域、低负载、长历史、布局复用和形状分布变化均具有明确的选择反转依据；开放或矛盾条件格不会被用于全局删除。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "候选在短请求格通过、在长请求格被容量排除时，可以作为带准入边界的短请求路径保留。"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "改变条件后保留状态不变量，重算成本并重新取得适用证据。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "竞争解释配有控制混杂的干预、观察边界与反证后的修正。正文和 classify 均在下界排除前检测同作用域约束矛盾，70/55/60 ms 反例进入 INCONSISTENT，R1-DIAG-01 已修复。有限回放、总体统计区间和设备验证的证据效力没有相互替代。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "若 L*>U*，先进入 `INCONSISTENT`，即使 L 已超过目标也不能提前按它排除。"
        },
        {
          "path": "knowledge/system-semantics/design-synthesis.md",
          "quote": "若关闭亲和同时降低命中率，就不能把总时间差单独归给路由。可通过预置相同合法缓存状态或分层报告实际命中，控制这个混杂。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "接受范围是设计推导、所供来源支持的机制及离线软件模型；没有目标 CPU/GPU 性能、真实 forward、模型质量、异步物理回收或 Agent 使用效果证据。正文已明确这些边界。",
    "classify 的合法性和容量为已决输入，证据有效性、作用域匹配、统计可采纳性和质量结论由调用者提供；检查不建立这些事实，也不验证统计覆盖率。",
    "集合参考穷举的是声明的有限整数耗时域，另检查有理数反例；它没有覆盖完整 SYNTHESIZE 搜索、容量未决规划或真实服务执行。",
    "原始论文和文档仅阅读所供摘录；S-CPU-TUNING 只有作者整理的机制说明。未读取源码归档、PDF 图片或未提供的原文部分，未实测离线链接存在性及页面渲染。",
    "实际执行依据用户提供的、绑定本轮脚本哈希的 actual_preflight 记录；本独立审阅未另行运行 Python，未把作者的 JavaScript 原型或上一轮执行当成本轮 Python 结果。"
  ],
  "checks": [
    {
      "script": "tools/check_k_sys_010_full.py",
      "args": []
    }
  ],
  "reading_scope": "全文阅读：AGENTS.md [0,567)、docs/knowledge-method.md [0,2251)、docs/knowledge-review.md [0,3016)、本轮 design-synthesis.md [0,19298)；9 份来源说明全文分别为 S-PAGED [0,2206)、S-SARATHI [0,1423)、S-DISTSERVE [0,443)、S-MLA [0,497)、S-NXDI [0,559)、S-CPU-TUNING [0,731)、S-GOTO [0,757)、S-INT8 [0,756)、S-STATS [0,983)。完整阅读 candidate.test_script 从导入到 main 入口、author_notes、三个 R1 findings 和 actual_preflight 执行记录。以下仅阅读所供摘录，范围均为材料标注的抽取文本零基半开字符区间，未将其登记为全文 documents。knowledge/ 下 [0,2236) 的相关章节：workloads/capacity-planning.md、hardware/cpu-linear-kernels.md、system-semantics/memory-allocators.md、workloads/session-workloads.md、tools/statistical-experiments.md、algorithms/prefix-cache-identity.md、algorithms/tiered-residency.md、algorithms/heterogeneous-execution.md、algorithms/parallelism.md、workloads/multi-model-placement.md、models/encoder-decoder-streaming.md、models/vision-language.md、models/speech-generation.md、models/embedding-reranking.md、system-semantics/retrieval-pipeline.md、models/vision-inference.md、models/recommendation-inference.md、models/graph-inference.md、workloads/cluster-resource-placement.md、system-semantics/storage-services.md、system-semantics/deployment-environment.md、algorithms/chunked-prefill.md、engine-index/vllm-scheduler.md、system-semantics/evidence-and-independent-checks.md、system-semantics/service-protocol.md、system-semantics/specialization-levers.md。knowledge/ 下其他摘录：algorithms/iteration-batching.md [4000,6236)；algorithms/heterogeneous-state-cache.md、frameworks/checkpoint-loading.md、algorithms/operator-primitives.md、models/omni-multimodal.md 各 [8000,10236)；frameworks/cuda-graph-buffers.md、frameworks/cpu-quantized-kernels.md、models/image-diffusion.md、models/video-generation.md 各 [12000,14236)；system-semantics/host-runtime.md、algorithms/disaggregated-serving.md 各 [4000,6236)；hardware/cuda-execution.md [16000,18236)。references/ 原文摘录：S-PAGED/fulltext.txt [4000,6232)、[8000,12000)、[16000,28000)、[44000,48000)、[64000,68000)；S-SARATHI/fulltext.txt [8000,16000)、[20000,22232)、[24000,32000)、[36000,40000)、[64000,68000)；S-DISTSERVE/fulltext.txt [28000,30233)、[32000,48000)、[72000,76000)、[80000,84000)；S-MLA/fulltext.txt [12000,20000)、[24000,32000)、[44000,48000)、[100000,102233)、[104000,108000)；S-NXDI/fulltext.txt [4000,8000)、[20000,24000)、[28000,38233)、[40000,48000)；S-GOTO/fulltext.txt [0,4000)、[8000,26233)、[28000,32000)；S-INT8/fulltext.txt [0,8000)、[12000,16000)、[20000,24000)、[28000,30233)、[44000,52000)；S-STATS/fulltext.txt [0,4000)、[32000,36000)、[48000,52000)、[68000,72000)、[108000,116000)、[156000,158232)。未把来源说明中记载的他人全文阅读算作本审阅的原文全文阅读。",
  "test_assessment": "独立检查了代码、数学依据及实际执行记录。资源参考将物理页展开为唯一 token 槽集合，将流量展开为带请求身份的读取列表，与被检函数的页大小累加采用不同表示；9 个唯一槽和 13 次逻辑读取能区分容量重复计数与流量错误去重。CPU 算例用手工展开的 Fraction 结果核对秒和 GiB，分类示例再显式转换到毫秒。分类参考枚举可行耗时集合并检查是否为空、是否全部满足目标，不复述 classify 的上下界分支顺序；声明的整数端点和阈值下，0..100 域保留了判断开放性所需的见证。检查覆盖 1920 组上下界、观测、作用域和质量组合，并有阈值相等、零目标、跨阈值区间、直接观测及合法性/容量分支。宽上界排除、质量 fail/unknown 绕过、矛盾检查前下界排除、下界当通过等错误变体确实被调用，并被集合参考拒绝，直接检验了本章修复的决策机制。39.0625≤50≤80 且 50≤60 的见证支持开放分类；70 下界与 55 上界支持矛盾分类。actual_preflight 的 script_sha256 与绑定值一致，Python 隔离执行 returncode=0、stderr 为空，输出与上述断言及覆盖数相符。该成功仅支持声明的软件模型范围。集合参考对两种时间排除标签和两种开放标签采用允许集合，因而穷举没有独立验证每个标签的证据归因；具体分支已通过代码审阅及定向断言核对。未执行或证明容量未决规划、多目标组合、真实逐层 forward、取消回收、统计区间生成、设备计时和质量评估，正文没有声称这些检查已通过。三项既有阻塞问题均可关闭，campaign 的语义修订要求已在完整候选重评中处理。"
}
